// Java oracle comparisons (testdata/b_java_oracle.json, regenerated by
// testdata/b_oracle/run.sh from the pinned Scouter sources + Jackson 2.12.6.1).

func TestBOracleStepJSON(t *testing.T) {
	o := bLoadOracle(t)
	if len(o.Steps) != 23 {
		t.Fatalf("oracle has %d steps, want all 23 StepEnum types", len(o.Steps))
	}
	objText := func(h int32) string {
		if h == 0 {
			return ""
		}
		return "object#" + strconv.Itoa(int(h))
	}
	for _, c := range o.Steps {
		raw, err := hex.DecodeString(c.Hex)
		if err != nil {
			t.Fatal(err)
		}
		steps, err := protocol.DecodeSteps(raw, protocol.Limits{})
		if err != nil || len(steps) != 1 {
			t.Fatalf("decode %s: %v", c.Hex, err)
		}
		js, err := bRawStepJSON(steps[0])
		if err != nil {
			t.Fatal(err)
		}
		if got := bMustJSON(t, js); got != c.JSON {
			t.Errorf("step %d\n got %s\nwant %s", steps[0].StepType(), got, c.JSON)
		}
		if c.SSpan == "" {
			continue
		}
		var got string
		switch v := steps[0].(type) {
		case *protocol.SpanStep:
			got = bMustJSON(t, bSSpanJSON(v.CommonSpanStep, nil, protocol.StepSpan, objText))
		case *protocol.SpanCallStep:
			got = bMustJSON(t, bSSpanJSON(v.CommonSpanStep, v, protocol.StepSpanCall, objText))
		}
		if got != c.SSpan {
			t.Errorf("sspan %d\n got %s\nwant %s", steps[0].StepType(), got, c.SSpan)
		}
	}
}

func TestBOracleXLogViews(t *testing.T) {
	o := bLoadOracle(t)
	raw, err := hex.DecodeString(o.XLog.Hex)
	if err != nil {
		t.Fatal(err)
	}
	p, err := protocol.DecodePack(raw, protocol.Limits{})
	if err != nil {
		t.Fatal(err)
	}
	x := p.(*protocol.XLogPack)
	if got := bMustJSON(t, bToSXLog(x)); got != o.XLog.SXLog {
		t.Errorf("SXLog\n got %s\nwant %s", got, o.XLog.SXLog)
	}
	// The oracle's TextProxy stub answers "<type>#<hash>".
	f, s, _ := bSetup(t, nil)
	dict := map[string]string{}
	for _, k := range []struct {
		typ string
		h   int32
	}{{"service", x.Service}, {"hmsg", x.ThreadNameHash}, {"error", x.Error}, {"ua", x.UserAgent}, {"referer", x.Referer},
		{"group", x.Group}, {"city", x.City}, {"login", x.Login}, {"hmsg", x.QueuingHostHash}, {"hmsg", x.Queuing2ndHostHash}} {
		dict[k.typ+":"+strconv.Itoa(int(k.h))] = k.typ + "#" + strconv.Itoa(int(k.h))
	}
	bTexts(f, dict)
	got := bMustJSON(t, s.bXLogDataList(context.Background(), []*protocol.XLogPack{x})[0])
	if got != o.XLog.XLogData {
		t.Errorf("XLogData\n got %s\nwant %s", got, o.XLog.XLogData)
	}
	// Old packets without the text append groups keep Java nulls.
	old := *x
	old.TailVersion = 6
	j := bMustJSON(t, bToSXLog(&old))
	for _, k := range []string{`"text1":null`, `"text2":null`, `"text3":null`, `"text5":null`, `"countryCode":"KR"`} {
		if !strings.Contains(j, k) {
			t.Errorf("old SXLog missing %s: %s", k, j)
		}
	}
}

func TestBOracleNumbersAndOrders(t *testing.T) {
	o := bLoadOracle(t)
	for _, d := range o.Doubles {
		bits, _ := strconv.ParseInt(d.Bits, 10, 64)
		v := math.Float64frombits(uint64(bits))
		if got := bJavaDouble(v); got != d.Double {
			t.Errorf("Double.toString(%v) = %s, want %s", v, got, d.Double)
		}
		if got := *bValueString(protocol.Value{Type: protocol.ValueDouble, Double: v}); got != d.DecimalValue {
			t.Errorf("DoubleValue.toString(%v) = %s, want %s", v, got, d.DecimalValue)
		}
	}
	for _, fl := range o.Floats {
		bits, _ := strconv.ParseInt(fl.Bits, 10, 32)
		v := math.Float32frombits(uint32(bits))
		if got := bJavaFloat(v); got != fl.Float {
			t.Errorf("Float.toString(%v) = %s, want %s", v, got, fl.Float)
		}
	}
	for _, c := range o.IntSets {
		if got := bJavaIntSet(c.In); !bEqualInts(got, c.Order) {
			t.Errorf("HashSet<Integer>%v order %v, want %v", c.In, got, c.Order)
		}
	}
	for _, c := range o.StringSets {
		if got := bJavaStringSet(c.In); !bEqualStrings(got, c.Order) {
			t.Errorf("HashSet<String>%v order %v, want %v", c.In, got, c.Order)
		}
	}
	for _, c := range o.Formats {
		params := ""
		for i, a := range c.Args {
			if i > 0 {
				params += "\x03"
			}
			params += a
		}
		if got := bBuildMessage(c.Format, params); got != c.Result {
			t.Errorf("buildMessasge(%q, %v) = %q, want %q", c.Format, c.Args, got, c.Result)
		}
	}
	for _, c := range o.SimpleDate {
		ms, ok := bParseLenientYmdHms(c.In, bKST)
		if c.Error != "" {
			if ok {
				t.Errorf("SimpleDateFormat %q: got %d, want %s", c.In, ms, c.Error)
			}
			continue
		}
		if !ok || strconv.FormatInt(ms, 10) != c.Millis {
			t.Errorf("SimpleDateFormat %q = %d/%v, want %s", c.In, ms, ok, c.Millis)
		}
	}
	for _, c := range o.LocalDateTime {
		ms, ok := bParseStrictLocal(c.In, c.Pattern == "yyyyMMddHHmm", bKST)
		if c.Error != "" {
			if ok {
				t.Errorf("LocalDateTime %s %q: got %d, want %s", c.Pattern, c.In, ms, c.Error)
			}
			continue
		}
		if !ok || strconv.FormatInt(ms, 10) != c.Millis {
			t.Errorf("LocalDateTime %s %q = %d/%v, want %s", c.Pattern, c.In, ms, ok, c.Millis)
		}
	}
	for _, c := range o.Shortener {
		if h := bJavaHash(c.URL); h != c.Hash || bHexa32(int64(h)) != c.Hexa32 {
			t.Errorf("shortener %q = %d/%s, want %d/%s", c.URL, h, bHexa32(int64(h)), c.Hash, c.Hexa32)
		}
	}
	for _, c := range o.Hexa32 {
		n, _ := strconv.ParseInt(c.N, 10, 64)
		if got := bHexa32(n); got != c.S {
			t.Errorf("Hexa32(%d) = %s, want %s", n, got, c.S)
		}
	}
}

func bEqualInts(a, b []int32) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func bEqualStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
